head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : mergeOptionStr = never / bycol / byrow (기본 병합 방식). bycolrec/byrowrec/byrestric* 는 _2~_4 담당.
scwin.tData = {
    "description" : "[gridView > M > mergeCellsFixedCols]<br/>GridView 컴포넌트의 mergeCellsFixedCols 속성을 설정합니다.",
    "validation" : [
        "fixedColumn, fixedRightColumn 속성으로 고정된 Column 영역에만 적용되며, fixedRow 로 고정된 Row 영역에는 적용되지 않습니다.",
        "mergeCellsFixedRows 속성 설정 시 mergeCellsFixedCols 속성은 무시됩니다.",
        "displayFormat 등의 포맷 속성이 적용되지 않은 원본 데이터와 초기 Column 위치를 기준으로 병합 처리됩니다.",
        "mergeOptionStr 'never' 설정 시 고정 Column 영역에서 동일 Cell 값에 대한 병합을 수행하지 않습니다.",
        "mergeOptionStr 'bycol' 설정 시 같은 Column 내에서 동일한 값이 연속되는 Cell 에 rowSpan 방식의 세로 병합을 수행합니다.",
        "mergeOptionStr 'byrow' 설정 시 같은 Row 내에서 동일한 값이 연속되는 Cell 에 colSpan 방식의 가로 병합을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 고정 영역(col1~col3) 과 비고정 영역(col4) 의 병합 차이를 보여주도록 구성. (P_mergeCellsFixedCols_1 과 동일 데이터)
//  · col1(고정) : A,A,B,B          → 세로(bycol) 동일값 연속 : [0~1]=A / [2~3]=B
//  · col2(고정) : P,P,P,P          → 행0 에서 col2=col3=P 가로(byrow) 동일값 / 세로도 동일값
//  · col3(고정) : P,Q,Q,R (행0 만 col2 와 같은 P) → 행0 가로병합 검증용
//  · col4(비고정,displayFormat) : 1000,1000,1000,1000 (원본 동일) → 비고정이라 어떤 옵션에서도 미병합(validation 고정영역 한정)
//    또 displayFormat="#,##0" 으로 표시값은 1,000 이나 병합은 원본(1000) 기준(원본 데이터 기준 validation)
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "P", "col3": "P", "col4": "1000" },
    { "col1": "A", "col2": "P", "col3": "Q", "col4": "1000" },
    { "col1": "B", "col2": "P", "col3": "Q", "col4": "1000" },
    { "col1": "B", "col2": "P", "col3": "R", "col4": "1000" }
];



// comp 생성 : fixedColumn=3 (col1~col3 고정) 그리드 1개를 동적 생성한다. (P_mergeCellsFixedCols_1 과 동일 구성)
//  ★ mergeCellsFixedCols 는 생성 attribute 로 주지 않는다. (초기 미병합 상태로 생성 후 mergeCellsFixedCols() 메소드로 적용)
//     col4 : 비고정 + displayFormat="#,##0" (원본 1000 vs 표시 1,000)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="fixedColumn=3(col1~col3 고정 → 병합 대상), col4=비고정+displayFormat(#,##0). 고정 영역만 병합되고 col4(비고정,동일값 1000)는 미병합. par_mergeOptionStr 선택 후 mergeCellsFixedCols 버튼으로 적용"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedColumn=3 으로 왼쪽 3개 컬럼 고정
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        fixedColumn: 3
    });

    // target 생성
    //  ★ 컬럼 폭 합(420)을 그리드 폭(300)보다 크게 하여 가로 스크롤이 생기도록 함 → col1~col3(좌측 고정)이 스크롤해도 그대로 남는 것을 확인.
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:300px;height:235px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedCols sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column2" value="col2(고정)"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column3" value="col3(고정)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column4" value="col4(비고정,포맷)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" dataType="number" displayFormat="#,##0" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCellsFixedCols 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCellsFixedCols(mergeOptionStr) 호출
scwin.btn_mergeCellsFixedCols_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCellsFixedCols(mode);

    bottom.setReturnValue("[옵션] mergeCellsFixedCols=" + target1.options.mergeCellsFixedCols + " / fixedColumn=" + target1.options.fixedColumn + " / mergeOptionStr='" + mode + "'");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 고정 영역 td 의 rowSpan/colSpan 을 직관 출력(⬇세로/➡가로) + 비고정(col4) 미병합 확인
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 고정 영역 td 는 _fixedColumnDiv 안에 위치하며 id 는 target1_cell_{row}_{col} 형태(scroll 영역과 중복 id 가능)
//  - 화면에 표시되는(흡수되지 않은) td 만 대상으로 rowSpan/colSpan 을 읽어 판정 (중복 키 제외)
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let col4Merged = false;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            // col4(비고정) = colIndex 3
            if (c === 3) col4Merged = true;
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "never (병합 없음)";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "bycol (세로 병합)";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "byrow (가로 병합)";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
    bottom.setReturnValue("비고정(col4) 영역 병합 여부 : " + col4Merged + " (false 면 비고정 영역 미병합 → 고정 영역에만 적용)");
}
